//! 🧪️ Shared artboard laws preserve the untouched original axis and refuse invalid dimensions.
use super::*;
#[test]fn original_page_artboard_projection_matches_neutral_laws(){let laws:serde_json::Value=serde_json::from_str(include_str!("../🔣️.json")).unwrap();for row in laws["cases"].as_array().unwrap(){let before=row["before"].as_array().unwrap();let after=row["after"].as_array().unwrap();let actual=dimensions(row["field"].as_str().unwrap(),row["value"].as_str().unwrap(),before[0].as_f64().unwrap(),before[1].as_f64().unwrap()).unwrap();assert_eq!([actual.width,actual.height],[after[0].as_f64().unwrap(),after[1].as_f64().unwrap()]);}for value in laws["refusals"].as_array().unwrap(){assert!(dimensions("pageDrawingWidth",value.as_str().unwrap(),200.0,100.0).is_err());}assert!(dimensions("pageDrawingWidth","1",200.0,0.0).is_err());assert!(dimensions("pageDrawingHeight","1",f64::NAN,100.0).is_err());}
